import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {readFile} from 'node:fs/promises';
import path from 'node:path';
export async function probe({call,observe,workspace}) {
  const file=path.join(workspace,'counterexample.xlsx');
  execFileSync('python3',[fileURLToPath(new URL('./fixture.py',import.meta.url)),file]);
  const original=await readFile(file);
  const inspection=await call('workbook_inspect',{file});
  assert.equal(inspection.isError,false,JSON.stringify(inspection));
  const report=JSON.parse(inspection.content[0].text);
  await observe('formula-uniformity', report.sheets[0].formula_runs);
  const recalculation=await call('workbook_recalculate',{file});
  assert.equal(recalculation.isError,false,JSON.stringify(recalculation));
  const values=JSON.parse(recalculation.content[0].text);
  await observe('native-recalculated-cell-types',values.formula_cells);
  assert.deepEqual(await readFile(file),original,'read-only diagnostics modified source');
  const actual=[1,2].map(row=>report.sheets[0].formula_runs.find(run=>run.row===row).uniform);
  actual.push(values.formula_cells.find(cell=>cell.cell==='A3').status,values.formula_cells.find(cell=>cell.cell==='B3').status);
  await observe('actual-versus-independent-expectation',{actual,expected:[true,true,'value','error']});
  assert.deepEqual(actual,[true,true,'value','error']);
}
